<?php $labels=['draft'=>'Rascunho','sent'=>'Liberado','viewed'=>'Visualizado','signed'=>'Assinado','cancelled'=>'Cancelado'];$rules=['percentage_commission'=>'Comissão percentual','fixed_monthly'=>'Mensalidade fixa','hybrid'=>'Mensalidade + comissão','per_enrollment'=>'Valor por matrícula'];$processing=['central_monthly_settlement'=>'Repasse mensal','central_automatic_split'=>'Split automático','franchise_asaas'=>'Asaas da franquia']; ?>
<div class="page-header"><div><p class="eyebrow">Franquias</p><h1>Contratos</h1><p>Histórico completo, renovações, assinatura e modelo comercial da rede.</p></div><a class="button button-secondary" href="<?= $escape($basePath) ?>/admin/franchise-contract-templates"><i class="fa-solid fa-file-pen"></i> Modelos</a></div>
<?php if(!empty($message)):?><div class="alert alert-success"><?= $escape($message) ?></div><?php endif;?><?php if(!empty($error)):?><div class="alert alert-danger"><?= $escape($error) ?></div><?php endif;?>
<div class="table-card"><table><thead><tr><th>Contrato</th><th>Franquia</th><th>Tipo</th><th>Regra</th><th>Processamento</th><th>Situação</th><th>Assinatura</th><th>Ação</th></tr></thead><tbody><?php foreach($contracts as$item):$rule=(string)($item['commercial_rule']??'');if($rule==='')$rule=($item['commercial_model']??'')==='fixed_plus_percentage'?((float)($item['sales_fee_percentage']??0)>0?'hybrid':'fixed_monthly'):'percentage_commission';$process=(string)($item['financial_processing']??'');if($process==='')$process=(float)($item['sales_fee_percentage']??0)>0?'central_automatic_split':'central_monthly_settlement';?><tr><td><span class="table-cell-stack"><strong>#<?= (int)($item['contract_number']??1) ?> · <?= $escape($item['title']) ?></strong><small><?= $item['valid_from']?$escape(date('d/m/Y',strtotime((string)$item['valid_from']))):'Sem início' ?> — <?= $item['valid_until']?$escape(date('d/m/Y',strtotime((string)$item['valid_until']))):'indeterminada' ?></small></span></td><td><span class="table-cell-stack"><strong><?= $escape($item['franchise_name']) ?></strong><small><?= $escape($item['cnpj']) ?></small></span></td><td><?= ($item['contract_type']??'new')==='renewal'?'Renovação':'Novo' ?></td><td><?= $escape($rules[$rule]??'Legado') ?></td><td><?= $escape($processing[$process]??'Não definido') ?></td><td><span class="status"><?= $escape($labels[$item['status']]??$item['status']) ?></span></td><td><?= $item['signed_at']?$escape(date('d/m/Y H:i',strtotime((string)$item['signed_at']))):'Pendente' ?></td><td><a class="button button-secondary button-small" href="<?= $escape($basePath) ?>/admin/franchise-contracts/<?= (int)$item['id'] ?>"><i class="fa-solid fa-eye"></i> Abrir</a></td></tr><?php endforeach;?><?php if($contracts===[]):?><tr><td colspan="8">Nenhum contrato gerado.</td></tr><?php endif;?></tbody></table></div>
